// Pattern Buffer - pattern buffer simulation (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var range=[40,12000,4000000], fid=[92.4,99.7,99.999];
console.log("Pattern Buffer - matter stream simulation");
console.log("==================================================");
for(var m=0;m<3;m++){
  var r=prng(1000+m*77); var ok=0,N=20000,dist=range[m]*0.5;
  for(var i=0;i<N;i++){ if(r()*100 < fid[m] - dist/range[m]*2) ok++; }
  console.log("Mark "+(m+1)+": range "+range[m]+" km, fidelity "+fid[m]+"%");
  console.log("  simulated "+N+" transports at half range: "+(100*ok/N).toFixed(2)+"% clean rematerialization");
}
console.log("Bio-filter interlock: any pattern below 99% fidelity is held, never transmitted.");

